--
-- Table structure for table `invoices`
--

DROP TABLE IF EXISTS `invoices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `invoices` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `invoice_no` varchar(100) DEFAULT NULL,
  `invoice_date` date DEFAULT NULL,
  `payment_mode` varchar(50) DEFAULT NULL,
  `customer_id` int(11) DEFAULT NULL,
  `place_of_supply` varchar(10) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `taxable_value` decimal(12,2) DEFAULT 0.00,
  `tax_total` decimal(12,2) DEFAULT 0.00,
  `total_amount` decimal(12,2) DEFAULT 0.00,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `discount` varchar(20) NOT NULL,
  `invoice_type` enum('gst','personal') DEFAULT 'gst',
  `serial_no` int(11) DEFAULT NULL,
  `status` enum('draft','sent','viewed','partially_paid','paid','overdue','cancelled') DEFAULT 'sent',
  `cancellation_reason` text DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `cancelled_by` int(11) DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `amount_paid` decimal(12,2) DEFAULT 0.00,
  `amount_due` decimal(12,2) DEFAULT 0.00,
  PRIMARY KEY (`id`),
  UNIQUE KEY `invoice_no` (`invoice_no`)
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

