INSERT INTO `leave_requests` VALUES (1,9,1,'2026-09-14','2026-09-14',1,'Dear Sir/Ma’am,\r\n\r\nI would like to request leave for today due to some urgent work at home. Kindly grant me leave for the day.\r\n\r\nThank you for your understanding.\r\n\r\nRegards,\r\nNeha Ghildiyal','approved',1,'2026-09-21 05:30:00','','2026-09-14 02:50:13','2026-09-21 05:30:00'),(2,2,1,'2026-09-23','2026-09-23',1,'kgxkdhlhf','rejected',1,'2026-09-24 01:55:32','','2026-09-22 11:12:54','2026-09-24 01:55:32'),(3,1,1,'2026-09-25','2026-09-25',1,'Rajkumar ne kha h leave lelo kl isley m nhi aaunga kl ok bye','rejected',1,'2026-09-24 11:54:42','tumahra yhi vaval rheta h kam par dyan do na ki londiya baji par.','2026-09-24 11:53:26','2026-09-24 11:54:42'),(4,5,1,'2026-09-28','2026-09-28',1,'Going to college to collect diploma.','approved',1,'2026-10-07 12:10:07','','2026-09-28 08:56:24','2026-10-07 12:10:07'),(5,6,1,'2026-09-28','2026-09-28',1,'To collect my Diploma and Migration Certificate from my college.','approved',1,'2026-10-07 12:10:19','','2026-09-28 09:26:42','2026-10-07 12:10:19'),(6,7,1,'2026-09-28','2026-09-28',1,'Out of station','approved',1,'2026-10-07 12:10:25','','2026-09-28 11:30:27','2026-10-07 12:10:25'),(7,8,1,'2026-10-03','2026-10-03',1,'There is a event in my house (Shraad) of my grand father','approved',1,'2026-10-07 12:10:53','','2026-10-01 10:16:43','2026-10-07 12:10:53'),(8,12,2,'2026-10-03','2026-10-03',1,'High fever and cold','approved',1,'2026-10-07 12:10:12','','2026-10-03 08:36:12','2026-10-07 12:10:12'),(9,12,1,'2026-10-22','2026-10-22',1,'Family function','approved',1,'2026-11-18 20:38:17','','2026-10-22 07:23:29','2026-11-18 20:38:17'),(10,8,1,'2026-11-20','2026-11-21',2,'GOING OUT FOR PERSONAL WORK','rejected',1,'2026-11-19 11:53:42','Your leave request for 20th–21st November is not approved.\r\n\r\nAs you have already availed 6 days of leave last month, and the team has also had an extended holiday period due to Diwali this month, we need to maintain regular attendance.\r\n\r\nWe have continuous shoots and client commitments scheduled throughout the remaining month. Therefore, no additional leaves can be approved until the end of November.\r\n\r\nPlease cooperate and ensure your availability as per the work schedule.','2026-11-12 17:45:47','2026-11-19 11:53:42');
